new='''pub fn redact_common_shapes(text: &str) -> String {
    // A pass can expose a shape another pass then matches (a URL nested in a password, a marker beside a quote), so
    // run until the text stops changing. Each change replaces non-marker text with a marker, so this settles fast; the
    // cap only bounds hostile input, and a text that settles is a fixed point, which is what makes this idempotent.
    let mut current = redact_pass(text);
    for _ in 0..MAX_PASSES {
        let next = redact_pass(&current);
        if next == current {
            break;
        }
        current = next;
    }
    current
}

/// Most extra passes [`redact_common_shapes`] makes while the text is still changing.
const MAX_PASSES: usize = 8;

fn redact_pass(text: &str) -> String {
    // Token shapes first: a `Bearer` token inside `auth=Bearer xyz` would otherwise be left behind when the key=value
    // pass only takes the word after the `=`. Userinfo goes before the key=value pass so a `?` inside a password
    // cannot be read as a query.
    let shaped = redact_token_shapes(text);
    let userinfo = redact_url_userinfo(&shaped);
    redact_secret_pairs(&userinfo)
}

